```js
import express from 'express';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import { z } from 'zod';

const app = express();
app.use(helmet());
app.use(express.json());
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));

const User = z.object({ name: z.string().min(1), email: z.string().email() });
const db = new Map();
let id = 1;

app.post('/users', (req, res, next) => {
  try {
    const u = User.parse(req.body);
    const row = { id: id++, ...u };
    db.set(row.id, row);
    res.status(201).json(row);
  } catch (e) { next(e); }
});
app.get('/users/:id', (req, res) => {
  const row = db.get(Number(req.params.id));
  if (!row) return res.status(404).json({ error: 'tiada' });
  res.json(row);
});
app.use((err, req, res, next) => res.status(400).json({ error: err.message }));
app.listen(3000);
```
Helmet + JSON + rate-limit dahulu, zod sahkan badan (400 automatik), handler ralat 4-argumen di akhir. Ganti Map dengan Prisma/Drizzle untuk prod.

```js
import express from 'express';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';

const app = express();
app.use(express.json());
const users = new Map(); // name -> { hash, refresh }
const sign = (u) => jwt.sign({ sub: u }, process.env.SECRET, { expiresIn: '15m' });

app.post('/register', async (req, res) => {
  const hash = await bcrypt.hash(req.body.pass, 12);
  users.set(req.body.name, { hash, refresh: null });
  res.status(201).json({ ok: true });
});
app.post('/login', async (req, res) => {
  const u = users.get(req.body.name);
  if (!u || !(await bcrypt.compare(req.body.pass, u.hash)))
    return res.status(401).json({ error: 'salah' });
  const refresh = nanoid();
  u.refresh = refresh;
  res.json({ access: sign(req.body.name), refresh });
});
const auth = (req, res, next) => {
  try {
    req.user = jwt.verify(req.headers.authorization?.split(' ')[1], process.env.SECRET).sub;
    next();
  } catch { res.status(401).json({ error: 'token' }); }
};
app.get('/me', auth, (req, res) => res.json({ user: req.user }));
```
bcrypt cost-12, akses 15 minit + refresh putar, middleware sahkan Bearer. Logout: padam refresh (denylist untuk akses jika perlu segera).

